def _get_db_conn():
    conn = mysql.connector.connect(**_DB_CONFIG)
    conn.ping(reconnect=True, attempts=3, delay=1)
    return conn

def update_step_status(experiment_id: str, step_name: str, new_status: str):
    conn = _get_db_conn()
    cursor = conn.cursor(dictionary=True)
    try:
        cursor.execute(
            "SELECT step_statuses FROM experiments WHERE id = %s",
            (experiment_id,)
        )
        row = cursor.fetchone()
        if not row:
            raise ValueError(f"Experiment with ID {experiment_id} not found.")

        try:
            statuses = json.loads(row["step_statuses"] or "[]")
        except Exception:
            raise ValueError("Invalid step_statuses JSON")

        updated = False
        for step in statuses:
            if step.get("step") == step_name:
                step["status"] = new_status
                updated = True
                break

        if not updated:
            statuses.append({"step": step_name, "status": new_status})

        cursor.execute(
            "UPDATE experiments SET step_statuses = %s WHERE id = %s",
            (json.dumps(statuses), experiment_id)
        )
        conn.commit()
    finally:
        cursor.close()
        conn.close()

