# ======================================================================
# MAIN GENERATOR
# ======================================================================

def generate_snakefile(steps: list[str], use_cloud: bool = False) -> str:

    select_ruleset("cloud" if use_cloud else "core")
    header = HEADER_CLOUD if use_cloud else HEADER_CORE
    parts = [header]

    # Insert selected step output blocks
    if use_cloud:
        for step in steps:
            if step in CLOUD_HEADER_STEP_BLOCKS:
                parts.append(CLOUD_HEADER_STEP_BLOCKS[step])

        # Build accumulator block EXACTLY like original Python version
        acc = ["\n# Accumulate outputs\nALL_RULE_INPUTS = []\n"]

        if "detect" in steps:
            acc.append("if DETECT_OUTPUT:\n    ALL_RULE_INPUTS += DETECT_OUTPUT\n")
        if "processing" in steps and "detect" not in steps:
            # Only add alignment outputs directly when detect is not also running
            # (detect rule already depends on processing.done as an input)
            acc.append("if ALIGN_OUTPUT:\n    ALL_RULE_INPUTS += ALIGN_OUTPUT\n")
        if "padlock" in steps:
            acc.append("if PADLOCK_OUTPUT:\n    ALL_RULE_INPUTS += PADLOCK_OUTPUT\n")
        if "conservation" in steps:
            acc.append("if CONSERVATION_OUTPUT:\n    ALL_RULE_INPUTS += CONSERVATION_OUTPUT\n")
        if "enrichment" in steps:
            acc.append("if ENRICHMENT_OUTPUT:\n    ALL_RULE_INPUTS += ENRICHMENT_OUTPUT\n")
        if "primer" in steps:
            acc.append("if PRIMER_OUTPUT:\n    ALL_RULE_INPUTS += PRIMER_OUTPUT\n")
        if "circtest" in steps:
            acc.append("if CIRCTEST_OUTPUT:\n    ALL_RULE_INPUTS += CIRCTEST_OUTPUT\n")
        if "nanopore" in steps:
            acc.append("if NANOPORE_OUTPUT:\n    ALL_RULE_INPUTS += NANOPORE_OUTPUT\n")
        if "ciriquant" in steps:
            acc.append("if CIRIQUANT_OUTPUT:\n    ALL_RULE_INPUTS += CIRIQUANT_OUTPUT\n")
        if "metatool" in steps:
            acc.append("if METATOOL_OUTPUT:\n    ALL_RULE_INPUTS += METATOOL_OUTPUT\n")
        if "sirna" in steps:
            acc.append("if SIRNA_OUTPUT:\n    ALL_RULE_INPUTS += SIRNA_OUTPUT\n")

        parts.append("\n".join(acc))

        # Insert rule all BELOW accumulator, BEFORE rules
        parts.append(dedent("""
        rule all:
            input:
                ALL_RULE_INPUTS
        """))
    else:
        parts.append("\n# Accumulate outputs (core mode)\nALL_RULE_INPUTS = []\n")

        for step in steps:
            if step == "check_inputs":
                parts.append("ALL_RULE_INPUTS.append('run_output/check.done')\n")
            elif step == "fastp":
                parts.append("ALL_RULE_INPUTS += expand('run_output/fastp/{sample}/fastp.done', sample=SAMPLES)\n")
            elif step == "remove_rrna":
                parts.append("ALL_RULE_INPUTS += expand('run_output/rrna/{sample}/remove_rrna.done', sample=SAMPLES)\n")
            elif step == "star_align":
                # NOTE: star_align's actual declared outputs (registry) are the STAR
                # result files themselves — there is no separate "star.done" marker —
                # so target those directly instead of a file no rule produces.
                parts.append(
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}_Aligned.out.sam', sample=SAMPLES)\n"
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}_Chimeric.out.junction', sample=SAMPLES)\n"
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}_SJ.out.tab', sample=SAMPLES)\n"
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}_Log.final.out', sample=SAMPLES)\n"
                )
            elif step == "star_align_mate1":
                parts.append(
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}.mate1_Aligned.out.sam', sample=SAMPLES)\n"
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}.mate1_Chimeric.out.junction', sample=SAMPLES)\n"
                )

            elif step == "star_align_mate2":
                parts.append(
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}.mate2_Aligned.out.sam', sample=SAMPLES)\n"
                    "ALL_RULE_INPUTS += expand('run_output/alignment/{sample}/{sample}.mate2_Chimeric.out.junction', sample=SAMPLES)\n"
                )

            elif step == "prep_circtools":
                parts.append("ALL_RULE_INPUTS.append('run_output/alignment/processing.done')\n")
            elif step == "detect":
                parts.append("ALL_RULE_INPUTS.append('run_output/circtools_ci/detect.done')\n")

                
                    
        parts.append(dedent("""
        rule all:
            input:
                ALL_RULE_INPUTS
        """))


        

    # Inject ciriquant finalizer if needed (cloud mode only)
    if use_cloud and "ciriquant" in steps:
        parts.append(dedent("""
        rule ciriquant_finalize:
            input:
                expand("run_output/ciriquant/{sample}/circ/{sample}.ciri", sample=SAMPLES)
            output:
                done="run_output/ciriquant/.ciriquant_done"
            shell:
                "touch {output.done}"
        """))

    # Append actual rules at end
    from snakebuilder.rules.registry import load_rules
    rules = load_rules()

    # In cloud mode, "processing" expands to the full set of alignment sub-rules.
    # fastp -> remove_rrna run ahead of STAR so reads are trimmed and
    # rRNA-depleted before alignment (see star_align's input, which consumes
    # remove_rrna's output instead of the raw sample fastqs, and remove_rrna's
    # input, which consumes fastp's output). build_bowtie2_index / build_star_index
    # are on their way out (indices are supplied pre-built by the genome catalog
    # now) — remove_rrna / star_align depend directly on the real index files
    # instead of a .done marker, so removing those two rules from this list
    # later won't break the dependency chain.
    PROCESSING_SUB_RULES = [
        "decompress_inputs",
        "fastp",
        "build_bowtie2_index",
        "remove_rrna",
        "build_star_index",
        "star_align",
        "star_align_mate1",
        "star_align_mate2",
        "prep_circtools_sample",
        "prep_circtools_finalize",
    ]

    # build_bwa_index / build_hisat2_index are on their way out (indices are
    # supplied pre-built by the genome catalog now) — ciriquant depends
    # directly on the real index files (bwa_index_files / hisat_index_files)
    # rather than a .done marker, so removing those two rules later won't
    # break the dependency chain.
    # build_ciriquant_filelist only needed when metatool is also running.
    CIRIQUANT_DEP_RULES = [
        "build_bwa_index",
        "build_hisat2_index",
    ] + (["build_ciriquant_filelist"] if "metatool" in steps else [])

    # "prep_circtools" isn't a real rule key in core_rules.json/cloud_rules.json —
    # it's a convenience name that should expand to both underlying rules.
    # (Re-added — this got dropped in the merge.)
    PREP_CIRCTOOLS_SUB_RULES = [
        "prep_circtools_sample",
        "prep_circtools_finalize",
    ]

    expanded_steps = []
    for step in steps:
        if step == "processing" and use_cloud:
            expanded_steps.extend(PROCESSING_SUB_RULES)
        elif step == "prep_circtools":
            expanded_steps.extend(PREP_CIRCTOOLS_SUB_RULES)
        elif step == "ciriquant" and use_cloud:
            expanded_steps.extend(CIRIQUANT_DEP_RULES)
            expanded_steps.append("ciriquant")
        else:
            expanded_steps.append(step)

    # Deduplicate while preserving order
    seen = set()
    deduped = []
    for s in expanded_steps:
        if s not in seen:
            seen.add(s)
            deduped.append(s)

    for step in deduped:
        parts.append(f"\n# --- {step.upper()} ---")
        if step not in rules:
            parts.append(f"# ⚠ Rule '{step}' not found\n")
        else:
            parts.append(get_rule(step))

    return "\n".join(parts)